head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setHeaderClass]<br/>Header Column 정보를 사용하여 특정 Header Column 에 CSS 클래스를 설정합니다.",
    "validation" : [
        "headerId(필수) 파라미터로 CSS 클래스를 설정할 Header Column 의 ID 를 설정해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - name / dept / memo 의 text Column 으로 구성 (마지막 memo Column width="*" 로 가로 스크롤 방지)
//  - 데이터 4행 바인딩
//  - Header Column ID(hcol_name/hcol_dept/hcol_memo) 로 setHeaderClass 호출하여 해당 Header th 에 클래스 적용
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John", "dept": "영업", "memo": "메모0" },
        { "name": "Jane", "dept": "기획", "memo": "메모1" },
        { "name": "Mike", "dept": "개발", "memo": "메모2" },
        { "name": "Sara", "dept": "인사", "memo": "메모3" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (name / dept / memo text Column, 마지막 memo Column width="*")
    //  - Header Column ID : hcol_name / hcol_dept / hcol_memo
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:520px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setHeaderClass 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol_name" value="이름"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol_dept" value="부서"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_memo" value="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// setHeaderClass 실행 : par_headerId(Header Column ID) / par_className 로 호출
//  - headerId 를 Header Column ID(hcol_name/hcol_dept/hcol_memo) 로 전달 → 해당 Header th 에 className 적용
scwin.btn_setHeaderClass_onclick = function () {
    let headerId = par_headerId.getValue();
    let className = par_className.getValue();

    // Header Column ID 로 Header Cell(th) 에 CSS 클래스 설정
    target1.setHeaderClass(headerId, className);
    wf_body_bottom.getObj("scwin").setReturnValue("setHeaderClass(" + headerId + ", " + className + ")");

    // getHeaderClass 로 설정값 확인 (내부 확인)
    let rtn = target1.getHeaderClass(headerId);
    wf_body_bottom.getObj("scwin").setReturnValue("getHeaderClass(" + headerId + ") : " + rtn);

    // 해당 Header th 에 className 이 적용되었는지 확인
    let cls = className.split(' ')[0];
    let appliedCount = document.querySelectorAll("th." + cls).length;
    wf_body_bottom.getObj("scwin").setReturnValue("className 적용 th 수 : " + appliedCount);
}
